// Generic arbitrary-H/default-method observer for unchanged rustc-stable-hash.
#![feature(hasher_prefixfree_extras)]
use rustc_stable_hash::{StableHasher,ExtendedHasher,FromStableHash};use serde_json::{Value,json};use std::{cell::RefCell,hash::Hasher,fmt,io::{self,BufRead}};
thread_local!{static LOG:RefCell<Vec<String>>=const{RefCell::new(Vec::new())};}
fn log(s:String){LOG.with(|v|v.borrow_mut().push(s))}fn hex(b:&[u8])->String{b.iter().map(|b|format!("{b:02x}")).collect()}fn bytes(s:&str)->Vec<u8>{s.as_bytes().chunks(2).map(|s|u8::from_str_radix(std::str::from_utf8(s).unwrap(),16).unwrap()).collect()}fn n(q:&Value,k:&str)->u64{q[k].as_u64().unwrap_or(0)}fn text<'a>(q:&'a Value,k:&str)->&'a str{q[k].as_str().unwrap_or("")}
struct Base{bytes:Vec<u8>}
impl Clone for Base{fn clone(&self)->Self{log("clone".into());Self{bytes:self.bytes.clone()}}fn clone_from(&mut self,other:&Self){log("h-clone-from".into());self.bytes.clone_from(&other.bytes)}}
impl Drop for Base{fn drop(&mut self){log(format!("drop-h:{}",hex(&self.bytes)))}}
impl fmt::Debug for Base{fn fmt(&self,f:&mut fmt::Formatter)->fmt::Result{log(format!("debug:alternate={}:width={:?}:fill={}",f.alternate(),f.width(),f.fill()));write!(f,"Base({})",self.bytes.len())}}
impl Hasher for Base{fn write(&mut self,b:&[u8]){log(format!("write:{}",hex(b)));self.bytes.extend_from_slice(b)}fn finish(&self)->u64{log(format!("finish64:{}",self.bytes.len()));self.bytes.len()as u64}fn write_u8(&mut self,v:u8){log(format!("u8:{v}"));self.bytes.push(v)}fn write_str(&mut self,v:&str){log(format!("str:{}",hex(v.as_bytes())));self.bytes.extend_from_slice(v.as_bytes());self.bytes.push(255)}fn write_length_prefix(&mut self,v:usize){log(format!("len:{v}"));self.bytes.extend_from_slice(&v.to_ne_bytes())}}
impl ExtendedHasher for Base{type Hash=Vec<u8>;fn finish(self)->Vec<u8>{log("finish-owned".into());self.bytes.clone()}}
struct Wrapped<const FULL:bool,const SHORT:bool>(Base);
impl<const F:bool,const S:bool>Clone for Wrapped<F,S>{fn clone(&self)->Self{Self(self.0.clone())}fn clone_from(&mut self,v:&Self){self.0.clone_from(&v.0)}}
impl<const F:bool,const S:bool>fmt::Debug for Wrapped<F,S>{fn fmt(&self,f:&mut fmt::Formatter)->fmt::Result{fmt::Debug::fmt(&self.0,f)}}
macro_rules! primitive{($($name:ident:$ty:ty),*)=>{$(fn $name(&mut self,v:$ty){if F{log(format!("{}:{}",stringify!($name).strip_prefix("write_").unwrap(),v));self.0.bytes.extend_from_slice(&v.to_ne_bytes())}else{self.0.$name(v)}})*};}
impl<const F:bool,const S:bool>Hasher for Wrapped<F,S>{fn write(&mut self,b:&[u8]){self.0.write(b)}fn finish(&self)->u64{Hasher::finish(&self.0)}fn write_u8(&mut self,v:u8){self.0.write_u8(v)}fn write_str(&mut self,v:&str){self.0.write_str(v)}fn write_length_prefix(&mut self,v:usize){self.0.write_length_prefix(v)}primitive!(write_u16:u16,write_u32:u32,write_u64:u64,write_u128:u128,write_usize:usize,write_i8:i8,write_i16:i16,write_i32:i32,write_i64:i64,write_i128:i128,write_isize:isize);}
impl<const F:bool,const S:bool>ExtendedHasher for Wrapped<F,S>{type Hash=Vec<u8>;fn short_write<const LEN:usize>(&mut self,b:[u8;LEN]){if S{log(format!("short:{LEN}:{}",hex(&b)));self.0.bytes.extend_from_slice(&b)}else{self.write(&b)}}fn finish(self)->Vec<u8>{ExtendedHasher::finish(self.0)}}
struct Out(Vec<u8>);impl Drop for Out{fn drop(&mut self){log(format!("drop-out:{}",hex(&self.0)))}}impl FromStableHash for Out{type Hash=Vec<u8>;fn from(v:Vec<u8>)->Self{log(format!("from:{}",hex(&v)));Self(v)}}
fn apply<H:Hasher>(h:&mut H,a:&Value){let v=n(a,"value");let wide=((n(a,"hi")as u128)<<64)|v as u128;match text(a,"op"){"bytes"=>h.write(&bytes(text(a,"bytes"))),"str"=>h.write_str(text(a,"text")),"len"=>h.write_length_prefix(v as usize),"u8"=>h.write_u8(v as u8),"u16"=>h.write_u16(v as u16),"u32"=>h.write_u32(v as u32),"u64"=>h.write_u64(v),"u128"=>h.write_u128(wide),"usize"=>h.write_usize(v as usize),"i8"=>h.write_i8(v as i8),"i16"=>h.write_i16(v as i16),"i32"=>h.write_i32(v as i32),"i64"=>h.write_i64(v as i64),"i128"=>h.write_i128(wide as i128),"isize"=>h.write_isize(v as isize),_=>panic!()}}
fn short<H:ExtendedHasher>(h:&mut H,a:&Value){let b=bytes(text(a,"bytes"));macro_rules! call{($($n:literal),*)=>{match n(a,"len"){$($n=>h.short_write::<$n>(b.as_slice().try_into().unwrap()),)*_=>panic!()}}}call!(0,1,2,4,8,9,10,16,32);}
fn run_t<const F:bool,const S:bool>(q:&Value){let base=Wrapped::<F,S>(Base{bytes:vec![]});if q["direct"].as_bool().unwrap_or(false){let mut h=base;for a in q["actions"].as_array().unwrap(){if text(a,"op")=="short"{short(&mut h,a)}else{apply(&mut h,a)}};let sum=Hasher::finish(&h);log(format!("sum:{sum}"));let result=ExtendedHasher::finish(h);log(format!("result:{}",hex(&result)))}else{let mut h=StableHasher::with_hasher(base);for a in q["actions"].as_array().unwrap(){apply(&mut h,a)};let mut cloned=h.clone();cloned.clone_from(&h);drop(cloned);log(format!("debug-text:{h:+#032?}"));let sum=Hasher::finish(&h);log(format!("sum:{sum}"));let out:Out=h.finish();log(format!("result:{}",hex(&out.0)));drop(out)}}
fn main(){for line in io::stdin().lock().lines(){let q:Value=serde_json::from_str(&line.unwrap()).unwrap();LOG.with(|v|v.borrow_mut().clear());match(q["full"].as_bool().unwrap(),q["short"].as_bool().unwrap()){(false,false)=>run_t::<false,false>(&q),(false,true)=>run_t::<false,true>(&q),(true,false)=>run_t::<true,false>(&q),(true,true)=>run_t::<true,true>(&q)}println!("{}",json!({"request":q,"result":LOG.with(|v|v.borrow().clone())}))}}
